/** Pixel Picture single-letter format print samples, generated by the same pipeline as Pages CI. */
import {readFile,writeFile,mkdir} from 'node:fs/promises';
import {createBookletPdf,getPrintableSheetRegions} from '../src/pdf.ts';
import {makeParityDraft} from './pr16f-fixtures.mjs';
const fonts={
 mouseMemoirs:await readFile(new URL('../fonts/MouseMemoirs-Regular.ttf',import.meta.url)),
 nunitoSans:await readFile(new URL('../fonts/Nunito-Medium.ttf',import.meta.url)),
 nunitoSans750:await readFile(new URL('../fonts/Nunito-Bold.ttf',import.meta.url)),
 nunitoSans900:await readFile(new URL('../fonts/Nunito-ExtraBold.ttf',import.meta.url)),
 zillaSlab:await readFile(new URL('../fonts/ZillaSlab-Bold-pdf.ttf',import.meta.url)),
};
await mkdir('artifacts',{recursive:true});
for(const [name,phrase,shapeId] of [
 ['star','The Egyptians chased after the Israelites.','star'],
 ['butterfly','The Israelites praised God because he made a way through the sea and kept them safe.','butterfly'],
]){
 const draft=makeParityDraft(6,{allBorderless:true});
 draft.title='God Makes a Way';
 draft.scripture='Exodus 14';
 draft.layouts[2]='medium-large';
 const region=getPrintableSheetRegions(draft).flat().find(r=>
  r.bookletPage===2&&r.size==='medium');
 if(!region)throw Error('No Medium slot for Pixel Picture PDF sample');
 draft.modules[region.bookletPage+':'+region.id]={
  type:'pixel-picture',phrase,shapeId,seed:3,
 };
 const pdf=await createBookletPdf(draft,fonts);
 const path='artifacts/sample-pr16m-single-letter-'+name+'.pdf';
 await writeFile(path,pdf);
 console.log('Wrote '+path+' ('+pdf.length+' bytes)');
}
